import numpy as np

# profiles: x from -100 to 100 step 20
profiles = {
150: np.array([3,1,10,16,30,35,29,15,7,3,1], dtype=float),
200: np.array([3,5,7,17,22,24,22,17,14,3,2], dtype=float),
250: np.array([4,4,8,11,12,17,14,12,14,6,3], dtype=float),
}
xs = np.arange(-100, 101, 20)

def interp(profile, x):
    return np.interp(x, xs, profile, left=0, right=0)

def overlap(profile, pitch, y, y_lines):
    return sum(interp(profile, y - yk) for yk in y_lines)

def line_positions(y0, y1, pitch, mode):
    # y0, y1 are extended region bounds
    if mode == "start":
        # lines at y0, y0+pitch, ... <= y1
        ys = []
        y = y0
        while y <= y1 + 1e-6:
            ys.append(y)
            y += pitch
        return ys
    if mode == "center_in":
        # first line at y0 + pitch/2, while center <= y1 - pitch/2? or <= y1
        ys = []
        y = y0 + pitch/2
        while y <= y1 - pitch/2 + 1e-6:
            ys.append(y)
            y += pitch
        return ys
    if mode == "cover":
        # lines spaced pitch, covering so that centers span y0 to y1 inclusive, centered
        span = y1 - y0
        n = int(np.floor(span / pitch)) + 1
        # n lines, total span of centers = (n-1)*pitch, centered in [y0,y1]
        extra = span - (n-1)*pitch
        start = y0 + extra/2
        return [start + i*pitch for i in range(n)]
    if mode == "ceil_start":
        ys = []
        y = y0
        # include a line if within region
        while y < y1 - 1e-9:
            ys.append(y)
            y += pitch
        ys.append(y1)  # always include both edges?
        return ys

# For a long field, uniformity vs pitch (ignore edges)
def field_uniformity(profile, pitch, n=8):
    # lines at 0, pitch, 2pitch...
    y_lines = [i*pitch for i in range(-2, n+3)]
    ys = np.linspace(0, pitch, 21, endpoint=False)  # one period
    vals = [overlap(profile, pitch, y, y_lines) for y in ys]
    return min(vals), max(vals), np.mean(vals), (max(vals)-min(vals))/np.mean(vals)

print("Field uniformity (min, max, mean, variation) for scale=1 (flow200/speed400)")
for standoff, prof in profiles.items():
